  const add = (...items) => items.forEach((item) => {
    if (!Array.isArray(item)) return warn('a skin in the queue must be [name, skin]. Skipped.');
    try { register(item[0], item[1]); } catch (error) { warn(`${error}. Skipped.`); }
  });
